SourceCode.Declaration:
public abstract class METCustomerMDFConsolidation
{
    CustAccount custAccount;
    InventSiteId siteId;
    InventLocationId warehouse;

}

Method.Source:
Query updateQuery(Query _query)
{
    QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(METCustomerMDFCalculationTrans));

    qbds.addRange(fieldNum(METCustomerMDFCalculationTrans, CustAccount)).value(custAccount);
    qbds.addRange(fieldNum(METCustomerMDFCalculationTrans, SiteId)).value(siteId);
    qbds.addRange(fieldNum(METCustomerMDFCalculationTrans, Warehouse)).value(warehouse);

    return _query;
}

void process()
{
    Query query = this.getQuery();
    query = this.updateQuery(query);

    QueryRun queryRun = new QueryRun(query);

    while(queryRun.next())
    {
        METCustomerMDFCalculationTrans calculationTransSum = queryRun.get(tableNum(METCustomerMDFCalculationTrans));

        this.processCalculationTransSum(calculationTransSum);
    }
}

void processCalculationTransSum(METCustomerMDFCalculationTrans _calculationTransSum)
{
    ttsbegin;

    RefRecId consolidationTableRecId = this.createConsolidationTable(_calculationTransSum);

    this.updateCalculationTrans(_calculationTransSum, consolidationTableRecId);

    ttscommit;
}

public RefRecId createConsolidationTable(METCustomerMDFCalculationTrans _calculationTransSum)
{
    METCustomerMDFConsolidationTable consolidationTableInsert;
    consolidationTableInsert.CustAccount = _calculationTransSum.CustAccount;
    consolidationTableInsert.ConsolidationMethod = this.getConslidationMethod();
    consolidationTableInsert.ShipDate = _calculationTransSum.ShipDate;
    consolidationTableInsert.ShipmentId = _calculationTransSum.ShipmentId;
    consolidationTableInsert.ApplicationMethod = this.getApplicationMethod();
    consolidationTableInsert.insert();
    return consolidationTableInsert.RecId;
}

public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;

    return custAccount;
}

public InventSiteId parmSiteId(InventSiteId _siteId = siteId)
{
    siteId = _siteId;

    return siteId;
}

public InventLocationId parmWarehouse(InventLocationId _warehouse = warehouse)
{
    warehouse = _warehouse;

    return warehouse;
}
